mapper.select:
SELECT COUNT(*) FROM wrong_questions
WHERE user_id = #{userId}
AND mastered = #{mastered}

SELECT id, user_id, canonical_key, expression, question_type, correct_answer, last_wrong_answer,
       wrong_count, correct_streak, mastered, last_practiced_at, created_at, updated_at
FROM wrong_questions
WHERE user_id = #{userId}
AND mastered = #{mastered}
ORDER BY mastered ASC, last_practiced_at DESC
LIMIT #{size} OFFSET #{offset}
